function catalog(){const p=new URLSearchParams(location.search),q0=p.get("q")||"",platform0=p.get("platform")||"",type=p.get("type")||"",seller0=p.get("seller")||"";document.title="Каталог — FPRES";$("main").innerHTML=`<section class="container page"><div class="breadcrumbs"><a href="index.html">Главная</a> / Каталог</div><h1 class="pageTitle">Каталог игр</h1><div class="toolbar"><input class="search" id="catQ" value="${q0.replaceAll('"',"&quot;")}" placeholder="Поиск игры, жанра или продавца"><select class="select" id="sort"><option value="popular">Популярные</option><option value="asc">Цена: ниже</option><option value="desc">Цена: выше</option><option value="rating">Рейтинг</option></select></div><div class="platforms" style="margin-bottom:15px">${D.platforms.map(x=>`<button class="platformChip ${(x==="Все"&&!platform0)||(x===platform0)?"active":""}" data-platform="${x}">${x==="Все"?'<span class="allPlatformIcon">✦</span>':platformLogo(x)}<span>${x}</span></button>`).join("")}</div><div class="catalogLayout"><aside class="filters"><div class="filterGroup"><h4>Категория</h4><div class="filterOptions">${[["","Все"],["games","Игры"],["keys","Ключи"],["dlc","DLC"],["services","Услуги"]].map(([v,l])=>`<button class="filterPill ${type===v?"active":""}" data-type="${v}">${l}</button>`).join("")}</div></div><div class="filterGroup"><h4>Платформа</h4><div class="filterOptions">${D.platforms.slice(1).map(v=>`<button class="filterPill ${platform0===v?"active":""}" data-platform2="${v}">${v}</button>`).join("")}</div></div><div class="filterGroup"><h4>Цена</h4><div class="priceRow"><input id="minP" type="number" placeholder="от"><input id="maxP" type="number" placeholder="до"></div></div><button class="btn primary" id="apply" style="width:100%">Применить</button></aside><section><div class="resultCount" id="count"></div><div class="gameGrid" id="grid"></div></section></div></section>`;
let chosenPlatform=platform0,chosenType=type;const render=()=>{let q=($("#catQ").value||"").toLowerCase(),min=+$("#minP").value||0,max=+$("#maxP").value||Infinity;let source=D.games;if(chosenType==="dlc")source=D.games.slice(0,20).map(g=>({...g,name:g.name+" · DLC",price:Math.max(299,Math.round(g.price*.35))}));if(chosenType==="services")source=D.games.slice(0,15).map(g=>({...g,name:g.name+" · Игровая услуга",price:299}));if(chosenType==="topup")source=D.games.slice(0,12).map(g=>({...g,name:g.name+" · Пополнение",price:499}));if(chosenType==="subscriptions")source=D.games.slice(0,10).map(g=>({...g,name:g.name+" · Подписка",price:799}));if(chosenType==="giftcards")source=D.games.slice(0,12).map(g=>({...g,name:g.platform+" · Подарочная карта "+g.name.split(" ")[0],price:[1000,2000,3000,5000][g.name.length%4]}));if(chosenType==="currency")source=D.games.slice(0,10).map(g=>({...g,name:g.name+" · Игровая валюта",price:349}));if(chosenType==="accounts")source=D.games.slice(0,10).map(g=>({...g,name:"Аккаунт · "+g.name,price:Math.round(g.price*1.4)}));let items=source.filter(g=>(!q||`${g.name} ${g.genre} ${g.seller}`.toLowerCase().includes(q))&&g.price>=min&&g.price<=max&&(!chosenPlatform||chosenPlatform==="Все"||g.group===chosenPlatform)&&(!seller0||g.seller===seller0));if($("#sort").value==="asc")items.sort((a,b)=>a.price-b.price);if($("#sort").value==="desc")items.sort((a,b)=>b.price-a.price);if($("#sort").value==="rating")items.sort((a,b)=>b.rating-a.rating);$("#grid").innerHTML=items.length?items.map(card).join(""):'<div class="panel empty"><h3>Ничего не найдено</h3><p>Попробуй изменить фильтры.</p></div>';$("#count").textContent=`Найдено ${items.length} из ${D.games.length} игр`};
$$("[data-type]").forEach(b=>b.onclick=()=>{chosenType=b.dataset.type;$$("[data-type]").forEach(x=>x.classList.remove("active"));b.classList.add("active");render()});$$("[data-platform]").forEach(b=>b.onclick=()=>{chosenPlatform=b.dataset.platform==="Все"?"":b.dataset.platform;$$("[data-platform]").forEach(x=>x.classList.toggle("active",b===x));render()});$$("[data-platform2]").forEach(b=>b.onclick=()=>{chosenPlatform=b.dataset.platform2;$$("[data-platform2]").forEach(x=>x.classList.remove("active"));b.classList.add("active");render()});$("#catQ").oninput=render;$("#sort").onchange=render;$("#apply").onclick=render;render();
}
