function cart(){const rows=S.cart.map(x=>({...x,g:game(x.id)})).filter(x=>x.g),total=rows.reduce((s,x)=>s+x.g.price*x.qty,0);document.title="Корзина — FPRES";$("main").innerHTML=`<section class="container page"><div class="breadcrumbs"><a href="index.html">Главная</a> / Корзина</div><h1 class="pageTitle">Корзина</h1>${rows.length?`<div class="twoCol"><div class="cartList">${rows.map(x=>`<div class="cartItem"><img src="${img(x.g.id)}" alt=""><div class="cartInfo"><b>${x.g.name}</b><span>${x.g.platform} · ${x.g.region} · ${x.g.seller}</span><span>⚡ Мгновенная выдача</span><div class="qty"><button data-dec="${x.g.id}">−</button><span>${x.qty}</span><button data-inc="${x.g.id}">+</button></div></div><div><b>${money(x.g.price*x.qty)}</b><br><button class="miniBuy" data-remove="${x.g.id}">Удалить</button></div></div>`).join("")}</div><aside class="cartSummary"><div class="summaryRow"><span>Товары</span><b>${money(total)}</b></div><div class="summaryRow"><span>Комиссия</span><b>0 ₽</b></div><div class="summaryRow total"><span>Итого</span><b>${money(total)}</b></div><a class="btn primary" href="checkout.html" style="width:100%;margin-top:14px">Перейти к оплате</a></aside></div>`:'<div class="panel empty"><h3>Корзина пуста</h3><p>Добавь игру из каталога.</p><a class="btn primary" href="catalog.html">В каталог</a></div>'}</section>`}
function checkout(){const rows=S.cart.map(x=>({...x,g:game(x.id)})).filter(x=>x.g),total=rows.reduce((s,x)=>s+x.g.price*x.qty,0);$("main").innerHTML=`<section class="container page"><div class="breadcrumbs"><a href="cart.html">Корзина</a> / Оплата</div><h1 class="pageTitle">Оформление заказа</h1>${rows.length?`<div class="twoCol"><div class="panel" style="padding:20px"><h3>Получатель</h3><div class="formGrid"><div class="fieldBlock"><label>Email</label><input class="field" id="email" value="${S.user?.email||""}" placeholder="you@example.com"></div><div class="fieldBlock"><label>Имя</label><input class="field" id="buyerName" value="${S.user?.name||""}" placeholder="PlayerOne"></div></div><h3 style="margin-top:20px">Способ оплаты</h3><div class="filterOptions"><button class="filterPill active" data-method="card">Карта</button><button class="filterPill" data-method="sbp">СБП</button></div><p style="color:#7f8b9d;font-size:11px;background:#0f1721;padding:12px;border-radius:10px;margin-top:14px">Демо-режим. Реального списания денег нет.</p><button class="buyWide" id="pay">Оплатить ${money(total)}</button></div><aside class="cartSummary"><h3>Ваш заказ</h3>${rows.map(x=>`<div class="summaryRow"><span>${x.g.name}${x.qty>1?" × "+x.qty:""}</span><b>${money(x.g.price*x.qty)}</b></div>`).join("")}<div class="summaryRow total"><span>Итого</span><b>${money(total)}</b></div></aside></div>`:'<div class="panel empty"><h3>Нет товаров для оплаты</h3><a class="btn primary" href="catalog.html">В каталог</a></div>'}</section>`;$("#pay")?.addEventListener("click",()=>{S.user={name:$("#buyerName").value||"PlayerOne",email:$("#email").value||"player@fpres.local"};const items=rows.map(x=>({id:x.g.id,price:x.g.price,key:"FPRES-"+Math.random().toString(36).slice(2,6).toUpperCase()+"-"+Math.random().toString(36).slice(2,6).toUpperCase()}));const orderNumber="FP-"+Math.floor(10000+Math.random()*89999);S.orders.unshift({number:orderNumber,date:new Date().toLocaleDateString("ru-RU"),status:"Выдан",total,items});S.cart=[];save();location.href="order.html?number="+encodeURIComponent(orderNumber)})}
