function global(){if(document.body.dataset.bound)return;document.body.dataset.bound="1";document.addEventListener("click",e=>{const t=e.target.closest("[data-add],[data-buy],[data-fav-game],[data-remove],[data-inc],[data-dec],[data-clear-cart],[data-login],[data-close],[data-enter],[data-copy],[data-add-product],[data-import],[data-withdraw],[data-close-modal],[data-save-product],[data-follow],[data-send-chat],[data-ticket],[data-copy-order],[data-method],[data-logout],[data-enter-direct],[data-seller-enter]");if(!t)return;const has=k=>Object.prototype.hasOwnProperty.call(t.dataset,k);if(t.dataset.add){e.stopPropagation();addCart(t.dataset.add);badges();return}if(t.dataset.buy){e.stopPropagation();buy(t.dataset.buy);return}if(t.dataset.favGame){e.stopPropagation();toggleFav(t.dataset.favGame);if(location.pathname.endsWith("product.html"))t.textContent=fav(t.dataset.favGame)?"♥ В избранном":"♡ Добавить в избранное";return}if(t.dataset.method){$("[data-method]").forEach(x=>x.classList.remove("active"));t.classList.add("active");toast("Способ оплаты: "+t.textContent.trim());return}if(t.dataset.remove){S.cart=S.cart.filter(x=>x.id!==t.dataset.remove);save();cart();return}if(t.dataset.inc||t.dataset.dec){const id=t.dataset.inc||t.dataset.dec,x=S.cart.find(i=>i.id===id);if(x){x.qty=Math.max(1,(x.qty||1)+(t.dataset.inc?1:-1));save();cart()}return}if(has("clearCart")){S.cart=[];save();cart();return}if(has("login")){if(S.user){location.href="account.html";return}$("#loginModal")?.classList.add("show");return}if(has("close")){if(location.pathname.endsWith("account.html")&&new URLSearchParams(location.search).get("auth")==="1"&&!S.user){location.href="index.html"}else{$("#loginModal")?.classList.remove("show")}return}if(has("enter")){S.user={name:$("#loginName").value.trim()||"PlayerOne",email:$("#loginEmail").value.trim()||"player@fpres.local"};save();$("#loginModal")?.classList.remove("show");location.href="account.html";return}if(t.dataset.copy){navigator.clipboard?.writeText(t.dataset.copy);toast("Ключ скопирован");return}if(t.dataset.follow){const id=t.dataset.follow;S.following=S.following.includes(id)?S.following.filter(x=>x!==id):[...S.following,id];save();seller();return}if(has("sendChat")){const v=$("#chatInput")?.value.trim();if(v){const b=document.createElement("div");b.className="bubble me";b.textContent=v;const box=$(".messages");box?.append(b);$("#chatInput").value="";toast("Сообщение отправлено");if(box){box.scrollTop=box.scrollHeight;setTimeout(()=>{const r=document.createElement("div");r.className="bubble";r.textContent="Спасибо за сообщение! Отвечу в ближайшее время.";box.append(r);box.scrollTop=box.scrollHeight},900)}}return}if(has("ticket")){toast("Обращение FP-HELP-1024 создано");return}if(has("addProduct")){const m=document.createElement("div");m.className="modalBack show";m.innerHTML='<div class="modal"><h3>Добавить товар</h3><p>Демо-форма продавца.</p><div class="fieldBlock"><label>Игра</label><input class="field" id="newProductName" value="Cyberpunk 2077"></div><div class="formGrid"><div class="fieldBlock"><label>Цена</label><input class="field" id="newProductPrice" type="number" value="2399"></div><div class="fieldBlock"><label>Остаток</label><input class="field" id="newProductStock" type="number" value="50"></div></div><div class="modalActions"><button class="btn" data-close-modal>Отмена</button><button class="btn primary" data-save-product>Добавить</button></div></div>';document.body.append(m);return}if(has("import")){const keys=prompt("Вставь демо-ключи, каждый с новой строки:");if(keys?.trim()){S.inventory.demo=(S.inventory.demo||[]).concat(keys.split(/\\n+/).map(x=>x.trim()).filter(Boolean));save();toast("Ключи импортированы: "+S.inventory.demo.length)}return}if(has("withdraw")){const amount=+($("#withdrawAmount")?.value||0);toast(amount>0?"Заявка на вывод "+money(amount)+" создана":"Укажи сумму вывода");return}if(has("closeModal")){t.closest(".modalBack")?.remove();return}if(has("saveProduct")){const n=$("#newProductName")?.value?.trim()||"Новый товар",p=+($("#newProductPrice")?.value||0),st=+($("#newProductStock")?.value||0);S.sellerProducts.push({name:n,price:p||499,stock:st||1});save();t.closest(".modalBack")?.remove();toast("Товар добавлен в демо");if(location.pathname.endsWith("seller-dashboard.html"))setTimeout(sellerDash,0);return}if(has("copyOrder")){toast("Данные заказа скопированы");return}if(has("enterDirect")){S.user={name:$("#loginNameDirect").value.trim()||"PlayerOne",email:$("#loginEmailDirect").value.trim()||"player@fpres.local"};save();location.href="account.html";return}if(has("sellerEnter")){const pw=$("#sellerLoginPassword")?.value||"";if(!pw){toast("Введите пароль");$("#sellerLoginPassword")?.focus();return}S.sellerUser={name:$("#sellerLoginName")?.value.trim()||"GameKey Store",email:$("#sellerLoginEmail")?.value.trim()||"seller@fpres.local"};save();sellerDash();return}if(Object.prototype.hasOwnProperty.call(t.dataset,"logout")){if(t.dataset.logout==="seller"){S.sellerUser=null}else{S.user=null}save();location.href="index.html";return}});document.addEventListener("click",e=>{const c=e.target.closest(".gameCard");if(c&&!e.target.closest("button"))location.href="product.html?id="+c.dataset.id});document.addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target.matches("[data-search]"))search(e.target.value)});}
